      let bestRank=-1;
      videoPreview.pause();
      for(let index=0;index<times.length;index++){
        const time=times[index];button.textContent=`Scanning video ${index+1}/${times.length} · ${formatTime(time)}`;
        await new Promise(resolve=>requestAnimationFrame(resolve));
        const frame=await captureVideoFrame(videoPreview,time),result=await inferFrame(activeSession,frame);
        videoFrames.push({timeSeconds:time,detections:result.detections,signature:visualSignature(frame),evidenceDataUrl:result.annotated.toDataURL('image/jpeg',.72)});
        const issue=result.detections.filter(d=>d.label==='triple_riding'||d.label==='no_helmet');
        const rank=issue.length?1+Math.max(...issue.map(d=>d.score)):Math.max(0,...result.detections.map(d=>d.score));
        if(rank>bestRank){bestRank=rank;annotated=result.annotated;evidenceTime=time;detections=result.detections;}
      }
