      sceneHost.querySelectorAll('[data-frame-index]').forEach(row=>{const selected=row===cue;row.classList.toggle('selected',selected);row.setAttribute('aria-pressed',String(selected));});
      const tripleCue=group.frames.filter(sample=>sample.detections.some(d=>d.label==='triple_riding')).length;
      const noHelmetCue=group.frames.filter(sample=>sample.detections.some(d=>d.label==='no_helmet')).length;
